  "claims_to_add": [],
  "hypothesis_update": {
    "action": "keep",
    "statement": ""
  }
}
{
  "claims_to_add": [],
  "hypothesis_update": {
    "action": "set",
    "statement": "The candidate observatory may be the one described."
  }
}
{
